30	/**
31	 * Groups owners into households and derives a household's stable shared identifier.
32	 * <p>
33	 * Two owners belong to the same household when they carry the same last name and the same
34	 * address. Both fields are compared leniently: surrounding whitespace is trimmed, internal
35	 * runs of whitespace are collapsed to a single space and letters are compared without
36	 * regard to case, so values that differ only in spacing or capitalisation are treated as
37	 * equal.
38	 */
39	@Component
40	public class HouseholdMatcher {
41	
42	    /** Runs of whitespace collapsed to a single space before comparison. */
43	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
44	
45	    private final ClinicService clinicService;
46	
47	    public HouseholdMatcher(ClinicService clinicService) {
48	        this.clinicService = clinicService;
49	    }
50	
51	    /**
52	     * Returns the already-stored owners that share {@code candidate}'s household under the
53	     * lenient comparison described above. The candidate itself is not yet stored, so it is
54	     * never included.
55	     *
56	     * @param candidate the owner being created
57	     * @return existing household members, possibly empty
58	     */
59	    public List<Owner> findMembers(Owner candidate) {
60	        String key = householdKey(candidate);
61	        return clinicService.findAllOwners().stream()
62	            .filter(existing -> householdKey(existing).equals(key))
63	            .toList();
64	    }
65	
66	    /**
67	     * The stable identifier for {@code candidate}'s household, derived deterministically
68	     * from its (normalised) last name and address so that every member resolves to the
69	     * same value.
70	     *
71	     * @param candidate an owner in the household
72	     * @return a non-blank household identifier
73	     */
74	    public String householdId(Owner candidate) {
75	        byte[] digest = sha256(householdKey(candidate));
76	        StringBuilder sb = new StringBuilder(12);
77	        for (int i = 0; i < 6; i++) {
78	            sb.append(String.format("%02X", digest[i]));
79	        }
80	        return sb.toString();
81	    }
82	
83	    private String householdKey(Owner owner) {
84	        return normalize(owner.getLastName()) + "\n" + normalize(owner.getAddress());
85	    }
86	
87	    private String normalize(String value) {
88	        if (value == null) {
89	            return "";
90	        }
91	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase(Locale.ROOT);
92	    }
93	
94	    private byte[] sha256(String value) {
95	        try {
96	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
97	        }
98	        catch (NoSuchAlgorithmException ex) {
99	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
100	        }
101	    }
102	}
